refentry.refsect1:
&reftitle.parameters;
database
La risorsa del database, restituita da dbase_open o da dbase_create.

&reftitle.changelog;





    &Version;
    &Description;





    PECL dbase 7.0.0

     database ora è una resource
     invece di un int.

  &reftitle.examples;



    Iterazione su tutti i record del database


<?php

// apre in modalità di sola lettura
$db = dbase_open('/tmp/test.dbf', 0);

if ($db) {
  $record_numbers = dbase_numrecords($db);
  for ($i = 1; $i <= $record_numbers; $i++) {
      $record = dbase_get_record($db, $i);
      if (!$record['deleted']) {
          // fa qualcosa con $record
      } else {
          // fa qualcosa con il $record eliminato oppure lo ignora
      }
  }
}

?>
